import http from 'k6/http';
import { check, sleep } from 'k6';
import exec from 'k6/execution';
import { Counter, Rate, Trend } from 'k6/metrics';

// Load fixtures generated by seed-tenants.py
const fixtures = JSON.parse(open('../ec2/fixtures-ec2.json'));
const tenants = fixtures.tenants;

const TARGET_HOST = __ENV.TARGET_HOST || '127.0.0.1';
const TARGET_PORT = __ENV.TARGET_PORT || '8080';
const DURATION = __ENV.BENCH_DURATION || '60s';

// Metrics per tenant role
const latSmall = new Trend('latency_small_acme', true);
const latMedium = new Trend('latency_medium_pool', true);
const latLarge = new Trend('latency_large_lotus', true);
const latFinance = new Trend('latency_standard_finance', true);
const latAggressor = new Trend('latency_aggressor', true);

const successRateNormal = new Rate('success_rate_normal');
const successRateAggressor = new Rate('success_rate_aggressor');
const rateLimitBlocked = new Counter('blocked_429_count');

// KB-2: Security check metrics
const securityChecksPassed = new Rate('kb2_security_checks_passed');
// KB-4: Customization check metrics
const kb4WipEnforced = new Rate('kb4_wip_strict_enforced');
const kb4SettingsLatency = new Trend('kb4_settings_latency', true);

export const options = {
  summaryTrendStats: ['avg', 'min', 'med', 'max', 'p(90)', 'p(95)', 'p(99)'],
  scenarios: {
    // Tenant 1: Acme Software (Small) - 15 concurrent users
    acme_small: {
      executor: 'constant-vus',
      vus: 15,
      duration: DURATION,
      exec: 'runSmallTenant',
      tags: { tenant: 't-acme', role: 'small' },
    },
    // Tenant 2: CTU Project Pool (Medium) - 15 concurrent users
    pool_medium: {
      executor: 'constant-vus',
      vus: 15,
      duration: DURATION,
      exec: 'runMediumTenant',
      tags: { tenant: 'pool-demo', role: 'medium' },
    },
    // Tenant 3: Lotus Media (Large) - 20 concurrent users
    lotus_large: {
      executor: 'constant-vus',
      vus: 20,
      duration: DURATION,
      exec: 'runLargeTenant',
      tags: { tenant: 't-lotus', role: 'large' },
    },
    // Tenant 4: FinTech Core (Standard) - 10 concurrent users
    finance_standard: {
      executor: 'constant-vus',
      vus: 10,
      duration: DURATION,
      exec: 'runFinanceTenant',
      tags: { tenant: 't-finance', role: 'standard' },
    },
    // Tenant 5: Aggressor (Noisy Neighbor) - 20 concurrent aggressive users
    aggressor_burst: {
      executor: 'constant-vus',
      vus: 20,
      duration: DURATION,
      exec: 'runAggressor',
      tags: { tenant: 't-aggressor', role: 'aggressor' },
    },
    // KB-2: Cross-tenant security probes — 1 dedicated VU runs throughout
    security_checks: {
      executor: 'constant-vus',
      vus: 1,
      duration: DURATION,
      exec: 'runSecurityChecks',
      tags: { scenario: 'kb2_security' },
    },
    // KB-4: WIP STRICT + customization checks — 1 dedicated VU runs throughout
    customization_checks: {
      executor: 'constant-vus',
      vus: 1,
      duration: DURATION,
      exec: 'runCustomizationChecks',
      tags: { scenario: 'kb4_customization' },
    },
  },
  thresholds: {
    'success_rate_normal': ['rate>0.95'],
    'latency_small_acme': ['p(95)<500'],
    'latency_medium_pool': ['p(95)<500'],
    'latency_large_lotus': ['p(95)<800'],
    // KB-2: 100% of security probes must be rejected (no cross-tenant data leak)
    'kb2_security_checks_passed': ['rate==1.0'],
    // KB-4: WIP STRICT must block 3rd move every iteration
    'kb4_wip_strict_enforced': ['rate>0.9'],
  },
};

function sendApiRequest(tenantData, vuId, path, method = 'GET', body = null, overrideToken = null) {
  const tokens = tenantData.tokens;
  // Pick dedicated user token for this VU
  const token = overrideToken !== null ? overrideToken : tokens[(vuId - 1) % tokens.length];
  const url = `http://${TARGET_HOST}:${TARGET_PORT}/api/v1${path}`;

  const headers = {
    'Host': tenantData.host,
    'Content-Type': 'application/json',
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  return http.request(method, url, body ? JSON.stringify(body) : null, {
    headers: headers,
    timeout: '10s',
  });
}

// User workflow: Normal active user with realistic think time
function runNormalUserWorkflow(tenantData, latencyTrend) {
  const vuId = exec.vu.idInInstance;
  const boardId = tenantData.boardId;

  // 1. Fetch Board & Tasks (Cache L1 / L2 test) - 70% frequency
  const resBoard = sendApiRequest(tenantData, vuId, `/boards/${boardId}`);
  const ok = resBoard.status === 200;
  successRateNormal.add(ok);
  latencyTrend.add(resBoard.timings.duration);

  // 2. Fetch Tenant Settings (Custom metadata L1 Caffeine test) - 30% frequency
  if (Math.random() < 0.3) {
    const resSettings = sendApiRequest(tenantData, vuId, '/tenant-settings/kanban');
    latencyTrend.add(resSettings.timings.duration);
    successRateNormal.add(resSettings.status === 200);
  }

  // 3. User Think Time (simulate active human interaction: 1.0s to 2.5s)
  sleep(Math.random() * 1.5 + 1.0);
}

export function runSmallTenant() {
  runNormalUserWorkflow(tenants['t-acme'], latSmall);
}

export function runMediumTenant() {
  runNormalUserWorkflow(tenants['pool-demo'], latMedium);
}

export function runLargeTenant() {
  runNormalUserWorkflow(tenants['t-lotus'], latLarge);
}

export function runFinanceTenant() {
  runNormalUserWorkflow(tenants['t-finance'], latFinance);
}

// Aggressor workflow: Continuous rapid-fire traffic without think time
export function runAggressor() {
  const vuId = exec.vu.idInInstance;
  const tenantData = tenants['t-aggressor'];
  const boardId = tenantData.boardId;

  const res = sendApiRequest(tenantData, vuId, `/boards/${boardId}`);
  if (res.status === 429) {
    rateLimitBlocked.add(1);
    successRateAggressor.add(false);
  } else {
    successRateAggressor.add(res.status === 200);
  }
  latAggressor.add(res.timings.duration);

  // Zero think time to generate intense traffic spike
  sleep(0.05);
}

// =============================================================================
// KB-2: Cross-Tenant Security Checks
// Tests that RLS and JWT tenant-claim validation prevent data leakage.
// =============================================================================
export function runSecurityChecks() {
  const acme = tenants['t-acme'];
  const lotus = tenants['t-lotus'];
  const acmeToken = acme.tokens[0];
  const lotusBoardId = lotus.boardId;

  // KB-1: Request WITHOUT a JWT token → must get 401
  const noAuthRes = http.get(
    `http://${TARGET_HOST}:${TARGET_PORT}/api/v1/boards/${acme.boardId}`,
    { headers: { 'Host': acme.host, 'Content-Type': 'application/json' }, timeout: '10s' }
  );
  const kb1Pass = check(noAuthRes, {
    'KB-1 no JWT → 401': (r) => r.status === 401,
  });
  securityChecksPassed.add(kb1Pass);

  // KB-2: acme user tries to read lotus board → must get 403 or 404 (RLS blocks it)
  const crossBoardRes = http.get(
    `http://${TARGET_HOST}:${TARGET_PORT}/api/v1/boards/${lotusBoardId}`,
    {
      headers: {
        'Host': acme.host,          // acme's host → JWT is scoped to acme tenant
        'Authorization': `Bearer ${acmeToken}`,
        'Content-Type': 'application/json',
      },
      timeout: '10s',
    }
  );
  const kb2Pass = check(crossBoardRes, {
    'KB-2 cross-tenant board → 403/404': (r) => r.status === 403 || r.status === 404,
  });
  securityChecksPassed.add(kb2Pass);

  // KB-2 variant: acme user tries to read a lotus task (if columns are available)
  if (lotus.columns && lotus.columns.length > 0) {
    const lotusFirstTask = `${lotusBoardId}`;  // board endpoint also validates RLS
    const crossTaskRes = http.get(
      `http://${TARGET_HOST}:${TARGET_PORT}/api/v1/projects`,
      {
        headers: {
          'Host': acme.host,
          'Authorization': `Bearer ${acmeToken}`,
          'Content-Type': 'application/json',
        },
        timeout: '10s',
      }
    );
    // /projects for acme must NOT contain any lotus project
    const projectsBody = crossTaskRes.json();
    const noLeak = check(crossTaskRes, {
      'KB-2 /projects response does not leak lotus data': (r) => {
        if (r.status !== 200) return true; // non-200 is also acceptable (RLS error)
        const body = r.json();
        const projects = Array.isArray(body) ? body : (body.content || []);
        return !projects.some(p => p.tenantId === lotus.tenantId);
      },
    });
    securityChecksPassed.add(noLeak);
  }

  sleep(2); // KB-2 probes run slowly — 1 VU, every ~2 seconds
}

// =============================================================================
// KB-4: Tenant Customization & WIP STRICT Enforcement
// Tests that JSONB custom_data, WIP limit enforcement, and tenant-settings
// apply correctly per tenant (t-acme uses STRICT/limit=2, t-lotus uses WARN/limit=10).
// =============================================================================
export function runCustomizationChecks() {
  const acme = tenants['t-acme'];  // STRICT WIP, limit=2
  const vuId = exec.vu.idInInstance;

  // KB-4a: GET /tenant-settings/kanban → verify settings cached correctly
  const settingsRes = sendApiRequest(acme, vuId, '/tenant-settings/kanban');
  kb4SettingsLatency.add(settingsRes.timings.duration);
  const settingsOk = check(settingsRes, {
    'KB-4 GET /tenant-settings/kanban → 200': (r) => r.status === 200,
    'KB-4 settings has wipMode field': (r) => {
      if (r.status !== 200) return false;
      const body = r.json();
      return body && body.settings && body.settings.wipMode !== undefined;
    },
  });
  successRateNormal.add(settingsOk);

  // KB-4b: POST a task with JSONB custom_data (story_points, sprint)
  const boardId = acme.boardId;
  const colId = acme.columns && acme.columns[0];
  if (colId) {
    const taskBody = {
      columnId: colId,
      title: `KB4 Load Task ${Date.now()}`,
      priority: 'MEDIUM',
      customData: { story_points: 5, sprint: 'Sprint Load' },
    };
    const createRes = sendApiRequest(acme, vuId, `/boards/${boardId}/tasks`, 'POST', taskBody);
    const created = check(createRes, {
      'KB-4 POST task with custom_data → 201': (r) => r.status === 201,
    });
    successRateNormal.add(created);

    if (created) {
      const task = createRes.json();

      // KB-4c: Move task to "In Progress" column (col index 1)
      const inProgressCol = acme.columns[1];
      if (inProgressCol && task && task.id) {
        const moveBody = {
          targetColumnId: inProgressCol,
          targetPosition: 9999,
          version: task.version || 0,
        };
        const moveRes = sendApiRequest(
          acme, vuId,
          `/boards/${boardId}/tasks/${task.id}/position`,
          'PATCH',
          moveBody
        );
        // With STRICT WIP (limit=2), moves beyond limit should return 422.
        // We track success for 200 (accepted) OR 422 (correctly blocked by WIP).
        // Both prove WIP enforcement is working — 422 is the proof of STRICT.
        const moveOk = check(moveRes, {
          'KB-4 PATCH task/position → 200 or 422 (WIP enforced)': (r) =>
            r.status === 200 || r.status === 422,
        });
        kb4WipEnforced.add(moveRes.status === 422); // 422 = WIP STRICT fired correctly
        successRateNormal.add(moveOk);
      }
    }
  }

  sleep(3); // KB-4 runs at ~1 iteration per 3s — thorough but low frequency
}
